@startuml

enum Unit {
  CELSIUS
  WATT
}

class SensorController {
  + Username : string
  + Password : string
}

class Apartment {
  + Address : string
  + EmailAddress : string
}

class Inhabitant {
  + Username : string
  + Password : string
  + IsAdministrator : boolean
}

class Room {
  + Description : string
}

class Sensor {
  + VendorId : string
  + Description : string
  + Unit : Unit
  + Threshold : float
  + LastValue : float
}

class TemperatureSensor extends Sensor {
  + MinValue : float
  + MaxValue : float
}

class PowerSensor extends Sensor {
  + CounterReading : float
}

class MeasuredValue {
  + Timestamp : datetime
  + Value : float
}

class EMonitor {
}

Apartment "1" -- "1" SensorController
Apartment "1" -- "1..*" Inhabitant
Apartment "1" -- "1..*" Room
SensorController "1" -- "0..*" Sensor
Sensor "1" -- "1" Room
Sensor "1" -- "0..*" MeasuredValue
Sensor "0..*" -- "1" EMonitor

@enduml

